/**
 * Migration safety scanner (Phase 1 destructive firewall).
 *
 * Scans generated Drizzle migration SQL for statements that can destroy
 * existing production data, and requires an explicit, committed
 * acknowledgment file before such a migration is allowed to ship or apply.
 *
 * This is the seatbelt for the failure mode where a schema edit (often an
 * innocent-looking column rename) is generated by drizzle-kit as a
 * DROP COLUMN + ADD COLUMN and silently deletes a column's data on the
 * next migrate. The scanner runs in three places:
 *   - CI (scripts/check-migration-safety.mjs) on every push / PR
 *   - the husky pre-commit hook (local, fast)
 *   - scripts/migrate.ts, at apply time, as the last line of defense on
 *     the machine actually mutating the database
 *
 * Acknowledgment convention: a migration `0003_foo.sql` that legitimately
 * needs a destructive statement must be accompanied by a committed,
 * non-empty file `0003_foo.destructive.md` in the same folder explaining
 * what data is being removed and why. Its presence is the human signal
 * "yes, this destruction is intentional."
 *
 * Pure data destruction is what we gate. We intentionally do NOT flag
 * DROP VIEW / DROP INDEX / DROP CONSTRAINT: views and indexes hold no
 * source-of-truth data, and Drizzle routinely drops and recreates
 * constraints and views as part of ordinary additive changes, so flagging
 * those would be noise that trains people to ignore the warning.
 */

import { readFileSync, readdirSync, existsSync } from "node:fs";
import path from "node:path";

/**
 * Rules that match a single SQL statement. Each `re` is tested against one
 * statement at a time (the SQL is split on `;` first), so a match means
 * that statement performs the named destructive action.
 */
const DESTRUCTIVE_RULES = [
  { label: "DROP TABLE", re: /\bDROP\s+TABLE\b/i },
  { label: "DROP COLUMN", re: /\bDROP\s+COLUMN\b/i },
  { label: "DROP SCHEMA", re: /\bDROP\s+SCHEMA\b/i },
  { label: "TRUNCATE", re: /\bTRUNCATE\b/i },
  { label: "DELETE FROM", re: /\bDELETE\s+FROM\b/i },
  {
    label: "ALTER COLUMN TYPE",
    re: /\bALTER\s+COLUMN\b[\s\S]*?\b(?:SET\s+DATA\s+TYPE|TYPE)\b/i,
  },
];

function condense(statement) {
  const collapsed = statement.replace(/\s+/g, " ").trim();
  return collapsed.length > 160 ? `${collapsed.slice(0, 157)}...` : collapsed;
}

/**
 * Return the destructive statements found in one migration's SQL.
 * @param {string} sql
 * @returns {{ rule: string, statement: string }[]}
 */
export function detectDestructiveStatements(sql) {
  // Strip block and line comments so commented-out SQL never trips a rule.
  const cleaned = sql
    .replace(/\/\*[\s\S]*?\*\//g, " ")
    .replace(/--.*$/gm, " ");

  const statements = cleaned.split(";");
  const found = [];
  for (const raw of statements) {
    const statement = raw.replace(/-->\s*statement-breakpoint/gi, " ").trim();
    if (!statement) continue;
    for (const rule of DESTRUCTIVE_RULES) {
      if (rule.re.test(statement)) {
        found.push({ rule: rule.label, statement: condense(statement) });
      }
    }
  }
  return found;
}

/**
 * Scan every committed migration in `migrationsDir`. Each migration that
 * contains destructive statements is sorted into `acknowledged` (a
 * matching non-empty `.destructive.md` exists) or `violations` (no ack).
 *
 * @param {string} migrationsDir absolute path to src/db/migrations
 * @returns {{
 *   violations: { file: string, ackFile: string, statements: { rule: string, statement: string }[] }[],
 *   acknowledged: { file: string, ackFile: string, statements: { rule: string, statement: string }[] }[],
 * }}
 */
export function scanMigrationsForDestructive(migrationsDir) {
  const violations = [];
  const acknowledged = [];
  if (!existsSync(migrationsDir)) {
    return { violations, acknowledged };
  }

  const files = readdirSync(migrationsDir)
    .filter((f) => f.endsWith(".sql"))
    .sort();

  for (const file of files) {
    const sql = readFileSync(path.join(migrationsDir, file), "utf8");
    const statements = detectDestructiveStatements(sql);
    if (statements.length === 0) continue;

    const ackFile = file.replace(/\.sql$/, ".destructive.md");
    const ackPath = path.join(migrationsDir, ackFile);
    const acknowledged_ =
      existsSync(ackPath) && readFileSync(ackPath, "utf8").trim().length > 0;

    if (acknowledged_) {
      acknowledged.push({ file, ackFile, statements });
    } else {
      violations.push({ file, ackFile, statements });
    }
  }

  return { violations, acknowledged };
}
